const {fitDataAsync, OPTIMIZERS} = DataScience;
const {x, y} = IO.loadSpiralData();
const nn = NeuralNet.builder()
    .input(2)
    .layer(20)
    .layer(1, NeuralNet.ACTIVATIONS.linear)
    .build();

const plot = IO.plotPointCloud(x, {
    aspect: "equal",
    radius: 0.022,
    color: y.map(label => label === 1 ? [1, 0, 0] : [0, 0, 1]),
    backgroundSampleSize: 4,
    background: point => {
        const prediction = nn.eval(point);
        const strength = 0.3 * Math.min(1, Math.abs(prediction));
        const base = 0.04;
        return prediction >= 0 ? [base + strength, base, base] : [base, base, base + strength];
    },
});

const updatePlot = ({theta, epoch, loss}) => {
    nn.setWeights(theta);
    if (epoch !== undefined) console.log(`Epoch ${epoch + 1}, loss: ${loss}`);
    plot.render();
};

setTimeout(() => {
    fitDataAsync(x, y, nn.model, {
        epochs: 3000,
        batch: 32,
        optimizer: OPTIMIZERS.ADAMW({learningRate: 0.01}),
        continuationEvery: 250,
        continuationFn: updatePlot,
    }).then(updatePlot).catch(error => console.error("Spiral training failed:", error));
});
plot;
